import React, { createContext, useState, useContext, useCallback } from 'react';
import { mockTransactions } from '../mockData';

// Create context
export const TransactionContext = createContext();

export const TransactionProvider = ({ children }) => {
  // State
  const [transactions, setTransactions] = useState(mockTransactions);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [currentTransaction, setCurrentTransaction] = useState(null);

  // Get all transactions
  const getTransactions = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      // Simulating API call
      await new Promise(resolve => setTimeout(resolve, 1000));
      setTransactions(mockTransactions);
    } catch (err) {
      setError('Failed to fetch transactions');
    } finally {
      setLoading(false);
    }
  }, []);

  // Get transaction by ID
  const getTransactionById = useCallback(async (id) => {
    setLoading(true);
    setError(null);
    try {
      // Simulating API call
      await new Promise(resolve => setTimeout(resolve, 500));
      const transaction = mockTransactions.find(t => t.id === id);
      setCurrentTransaction(transaction);
      return transaction;
    } catch (err) {
      setError('Failed to fetch transaction details');
      return null;
    } finally {
      setLoading(false);
    }
  }, []);

  // Add new transaction
  const addTransaction = useCallback(async (newTransaction) => {
    setLoading(true);
    setError(null);
    try {
      // Simulating API call
      await new Promise(resolve => setTimeout(resolve, 1000));
      const transaction = {
        ...newTransaction,
        id: `TX${Date.now()}`,
        date: new Date().toISOString(),
        status: 'pending'
      };
      setTransactions(prev => [transaction, ...prev]);
      return transaction;
    } catch (err) {
      setError('Failed to create transaction');
      return null;
    } finally {
      setLoading(false);
    }
  }, []);

  // Update transaction status
  const updateTransactionStatus = useCallback(async (id, status) => {
    setLoading(true);
    setError(null);
    try {
      // Simulating API call
      await new Promise(resolve => setTimeout(resolve, 500));
      setTransactions(prev =>
        prev.map(transaction =>
          transaction.id === id
            ? { ...transaction, status }
            : transaction
        )
      );
      return true;
    } catch (err) {
      setError('Failed to update transaction status');
      return false;
    } finally {
      setLoading(false);
    }
  }, []);

  // Delete transaction
  const deleteTransaction = useCallback(async (id) => {
    setLoading(true);
    setError(null);
    try {
      // Simulating API call
      await new Promise(resolve => setTimeout(resolve, 500));
      setTransactions(prev => prev.filter(transaction => transaction.id !== id));
      return true;
    } catch (err) {
      setError('Failed to delete transaction');
      return false;
    } finally {
      setLoading(false);
    }
  }, []);

  // Filter transactions
  const filterTransactions = useCallback((filters) => {
    const searchTerm = filters.search?.toLowerCase();
    return transactions.filter(transaction => {
      if (filters.type && transaction.type !== filters.type) return false;
      if (filters.status && transaction.status !== filters.status) return false;
      if (searchTerm) {
        return (
          transaction.id.toLowerCase().includes(searchTerm) ||
          transaction.description?.toLowerCase().includes(searchTerm) ||
          transaction.recipient?.toLowerCase().includes(searchTerm) ||
          transaction.sender?.toLowerCase().includes(searchTerm)
        );
      }
      return true;
    });
  }, [transactions]);

  // Calculate transaction statistics
  const getTransactionStats = useCallback(() => {
    return transactions.reduce((stats, transaction) => {
      if (transaction.type === 'send') {
        stats.totalSent += transaction.amount;
      } else {
        stats.totalReceived += transaction.amount;
      }
      if (transaction.status === 'pending') {
        stats.pendingAmount += transaction.amount;
      }
      return stats;
    }, {
      totalSent: 0,
      totalReceived: 0,
      pendingAmount: 0
    });
  }, [transactions]);

  // Context value
  const value = {
    transactions,
    loading,
    error,
    currentTransaction,
    getTransactions,
    getTransactionById,
    addTransaction,
    updateTransactionStatus,
    deleteTransaction,
    filterTransactions,
    getTransactionStats,
    setTransactions,
    setError,
    setCurrentTransaction
  };

  return (
    <TransactionContext.Provider value={value}>
      {children}
    </TransactionContext.Provider>
  );
};

// Custom hook for using transaction context
export const useTransactions = () => {
  const context = useContext(TransactionContext);
  if (!context) {
    throw new Error('useTransactions must be used within a TransactionProvider');
  }
  return context;
};

export default TransactionContext;
